const std = @import("std");
const zdate = @import("zdate");
const ZDate = zdate.ZDate;

// Differential test against V8: every expected value below is V8's actual
// output, captured with `TZ=America/Santiago node -e ...` on the same IANA
// tzdata release as the embedded fixture.
const santiago_tzif = @embedFile("fixtures/america_santiago.tzif");

test "z-date matches V8 exactly for the same zone" {
    const tz = try zdate.Timezone.parseBytes(std.testing.allocator, santiago_tzif);
    ZDate.setLocalTimezone(tz);
    defer ZDate.clearLocalTimezone();

    // getTimezoneOffset
    try std.testing.expectEqual(@as(i32, 240), ZDate.fromTimestamp(ZDate.UTC(2024, 5, 15, 12, 0, 0, 0)).getTimezoneOffset().?);
    try std.testing.expectEqual(@as(i32, 180), ZDate.fromTimestamp(ZDate.UTC(2024, 11, 15, 12, 0, 0, 0)).getTimezoneOffset().?);

    // local getters
    try std.testing.expectEqual(@as(i32, 8), ZDate.fromTimestamp(ZDate.UTC(2024, 5, 15, 12, 0, 0, 0)).getHours().?);

    // local->UTC including DST disambiguation (exact V8 ms values)
    try std.testing.expectEqual(@as(i64, 1712457000000), ZDate.fromComponents(2024, 3, 6, 23, 30, 0, 0).getTime());
    try std.testing.expectEqual(@as(i64, 1725769800000), ZDate.fromComponents(2024, 8, 8, 0, 30, 0, 0).getTime());
    try std.testing.expectEqual(@as(i64, 1718461800000), ZDate.fromComponents(2024, 5, 15, 10, 30, 0, 0).getTime());

    // ISO date-time without offset is local
    try std.testing.expectEqual(@as(i64, 1718460000000), ZDate.parse("2024-06-15T10:00:00"));

    // POSIX-rule extrapolation matches V8/ICU far beyond the table
    try std.testing.expectEqual(@as(i32, 180), ZDate.fromTimestamp(ZDate.UTC(2200, 0, 15, 12, 0, 0, 0)).getTimezoneOffset().?);
    try std.testing.expectEqual(@as(i32, 240), ZDate.fromTimestamp(ZDate.UTC(2200, 5, 15, 12, 0, 0, 0)).getTimezoneOffset().?);
}

