test "150 random V8 cases: UTC getters, toISOString, and ISO round-trip agree" {
    const allocator = std.testing.allocator;
    for (cases) |c| {
        const date = ZDate.fromTimestamp(c.ts);
        try std.testing.expectEqual(c.y, date.getUTCFullYear().?);
        try std.testing.expectEqual(c.mo, date.getUTCMonth().?);
        try std.testing.expectEqual(c.d, date.getUTCDate().?);
        try std.testing.expectEqual(c.wd, date.getUTCDay().?);
        try std.testing.expectEqual(c.h, date.getUTCHours().?);
        try std.testing.expectEqual(c.mi, date.getUTCMinutes().?);
        try std.testing.expectEqual(c.s, date.getUTCSeconds().?);
        try std.testing.expectEqual(c.ms, date.getUTCMilliseconds().?);

        const iso = try date.toISOString(allocator);
        defer allocator.free(iso);
        try std.testing.expectEqualStrings(c.iso, iso);

        // And V8's own ISO output parses back to the exact timestamp.
        try std.testing.expectEqual(c.ts, ZDate.parse(c.iso));
    }
}
